from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        if kind == 'put':
            value = op[3]
            if key in cache:
                if is_expired(key, t):
                    del cache[key]
                else:
                    cache.pop(key)
            if key not in cache and len(cache) >= capacity:
                # evict LRU, but only need to evict if we're actually adding new entry
                cache.popitem(last=False)
            cache[key] = (value, t)
            cache.move_to_end(key)
        else:  # get
            if key in cache and not is_expired(key, t):
                value, wt = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)

    return results

